import type { TabActionButtonProps } from "./tab";

import { forwardRef } from "react";
import { Close, ChevronDown } from "@exp-textura/icons";
import { clsx } from "clsx";
import { IconButton } from "@components/icon-button";

import { TabClasses } from "./tab";

export const TabActionButton = forwardRef<HTMLButtonElement, TabActionButtonProps>(
  ({ action, className, children, ...props }, ref) => {
    const Icon = action === "close" ? Close : ChevronDown;
    const buttonClasses = clsx(TabClasses.actionButton, className);

    return (
      <IconButton
        ref={ref}
        aria-hidden="true"
        aria-label={props["aria-label"] ?? (action === "close" ? "Close tab" : "Tab actions")}
        // @ts-expect-error this is not a prop we want exposed to others, but works with emotion styled to solve accessibility issues here
        as="div"
        buttonType="secondary"
        className={buttonClasses}
        size="sm"
        tabIndex={-1}
        onPointerDown={(e) => {
          e.preventDefault();
          e.stopPropagation();
        }}
        {...props}
      >
        {children || <Icon />}
      </IconButton>
    );
  },
);

TabActionButton.displayName = "Tab.ActionButton";
